80	pub(crate) fn parse_root(p: &mut HtmlParser) {
81	    let m = p.start();
82	
83	    p.eat(UNICODE_BOM);
84	
85	    if p.at(T![---]) {
86	        HtmlSyntaxFeatures::Astro
87	            .parse_exclusive_syntax(
88	                p,
89	                |p| parse_astro_fence(p),
90	                |p, m| {
91	                    p.err_builder("Frontmatter is only valid inside Astro files.", m.range(p))
92	                        .with_hint("Remove it or rename the file to have the .astro extension.")
93	                },
94	            )
95	            .ok();
96	    }
97	
98	    // Whether or not frontmatter was present, once we're past the frontmatter
99	    // position `---` can no longer start a fence. This prevents `---` in HTML
100	    // content from being incorrectly lexed as a FENCE token.
101	    p.set_after_frontmatter(true);
102	
103	    parse_doc_type(p).ok();
104	    ElementList.parse_list(p);
105	
106	    m.complete(p, HTML_ROOT);
107	}
