143	/// We need to treat `:`, `.` and `@` differently if we are in a Vue or Astro context.
144	///
145	/// Normally, we would do this using [`HtmlSyntaxFeatures`], and we do this elsewhere.
146	/// However, this makes it so that these characters are disallowed and using them
147	/// will emit diagnostics. We want to allow them if they have no special meaning.
148	#[inline(always)]
149	fn inside_tag_context(p: &HtmlParser) -> HtmlLexContext {
150	    if Vue.is_supported(p) {
151	        HtmlLexContext::InsideTagWithDirectives { svelte: false }
152	    } else if Svelte.is_supported(p) {
153	        HtmlLexContext::InsideTagSvelte
154	    } else if Astro.is_supported(p) {
155	        HtmlLexContext::InsideTagAstro
156	    } else {
157	        HtmlLexContext::InsideTag
158	    }
159	}
