174	#[inline(always)]
175	fn component_name_context(p: &HtmlParser) -> HtmlLexContext {
176	    if Vue.is_supported(p) || Svelte.is_supported(p) || Astro.is_supported(p) {
177	        // Use HtmlLexContext::InsideTagWithDirectives for all component-supporting files when parsing component names
178	        // This allows `.` to be lexed properly for member expressions
179	        // Note: This is safe because we only use this context for tag names, not attributes
