132	    /// Change the kind of node this marker represents
133	    pub fn change_kind<P>(&mut self, p: &mut P, new_kind: P::Kind)
134	    where
135	        P: Parser,
136	    {
137	        match p
138	            .context_mut()
139	            .events
140	            .get_mut(self.start_pos as usize)
141	            .expect("Finish position of marker is OOB")
142	        {
143	            Event::Start { kind, .. } => {
144	                *kind = new_kind;
145	            }
