182	    /// This method allows to create a new node which starts
183	    /// *before* the current one. That is, parser could start
184	    /// node `A`, then complete it, and then after parsing the
185	    /// whole `A`, decide that it should have started some node
186	    /// `B` before starting `A`. `precede` allows to do exactly
187	    /// that. See also docs about `forward_parent` in `Event::Start`.
188	    ///
189	    /// Given completed events `[START, FINISH]` and its corresponding
190	    /// `CompletedMarker(pos: 0, _)`.
191	    /// Append a new `START` events as `[START, FINISH, NEWSTART]`,
192	    /// then mark `NEWSTART` as `START`'s parent with saving its relative
193	    /// distance to `NEWSTART` into forward_parent(=2 in this case);
194	    pub fn precede<P>(self, p: &mut P) -> Marker
195	    where
196	        P: Parser,
197	    {
198	        let mut new_pos = p.start();
199	        let idx = self.start_pos as usize;
200	        match p.context_mut().events[idx] {
201	            Event::Start {
202	                ref mut forward_parent,
203	                ..
204	            } => {
205	                // Safety: The new marker is always inserted after the start marker of this node, thus
206	                // subtracting the two positions can never be 0.
207	                *forward_parent = Some(NonZeroU32::try_from(new_pos.pos - self.start_pos).unwrap());
208	            }
209	            _ => unreachable!(),
210	        }
211	        new_pos.child_idx = Some(self.start_pos as usize);
212	        new_pos.start = self.offset;
213	        new_pos.old_start(self.old_start)
214	    }
