216	    /// Undo this completion and turns into a `Marker`
217	    pub fn undo_completion<P>(self, p: &mut P) -> Marker
218	    where
219	        P: Parser,
220	    {
221	        let start_idx = self.start_pos as usize;
222	        let finish_idx = self.finish_pos as usize;
223	
224	        let events = &mut p.context_mut().events;
225	
226	        match events[start_idx] {
227	            Event::Start {
