/// Checks whether the parser is positioned at a closing tag for a void element,
/// e.g. `</br>` or `</img>`.
///
/// Void elements are always self-closing and should never have a closing tag.
/// Such a stray closing tag must not be treated as a closing tag for an
/// enclosing element, so we detect it here in order to consume it as a bogus
/// element instead.
fn is_at_void_closing_tag(p: &mut HtmlParser) -> bool {
    if !p.at(T![<]) || !p.nth_at(1, T![/]) {
        return false;
    }

    // The tag name follows `</`, but the lexer only exposes the *kind* of
    // lookahead tokens, not their text. Speculatively consume `</` so we can
    // inspect the tag name, then rewind back to where we started.
    let checkpoint = p.checkpoint();
    p.bump_with_context(T![<], inside_tag_context(p));
    p.bump_with_context(T![/], inside_tag_context(p));
    let is_void = is_at_start_literal(p)
        && VOID_ELEMENTS
            .iter()
            .any(|tag| tag.eq_ignore_ascii_case(p.cur_text()))
        && !is_possible_component(p, p.cur_text());
    p.rewind(checkpoint);
